public static AAXSalesPackingSlipPostedBusinessEvent newFromCustPackingSlipJour(CustPackingSlipJour _custPackingSlipJour)
{
    AAXSalesPackingSlipPostedBusinessEvent businessEvent = new AAXSalesPackingSlipPostedBusinessEvent();
    businessEvent.parmCustPackingSlipJour(_custPackingSlipJour);

    return businessEvent;
}

